+                        () -> new ParameterizedMessage(
+                            "[{}] model is [{}] but failed to notify master",
+                            modelId,
+                            routingStateAndReason.getState()
+                        ),
+                        error
+                    );
+                    listener.onFailure(error);
+                }
+            )
